// Generated by bitkit from bitkit.kit.json (schema bitkit.kit/v1) at 2026-11-08T20:00:00Z. Edit the JSON, not this file.
import { WorkflowEntrypoint, type WorkflowEvent, type WorkflowStep } from "cloudflare:workers";
import bitkit from "./generator.js";

type Tenant = { slug: string; script: string; hostname: string; owner: string; status: string };
type KitRecord = { id: string; slug: string; name: string; published_at: number };
const APEX = "bitkit.sh";
// The kit API and setup scripts live on app.<zone>; every other <slug>.<zone> is a tenant.
const APP = `app.${APEX}`;
export const RESERVED_SLUGS = new Set(["app", "www", "api", "admin", "mail"]);

const b32 = (bytes: Uint8Array) => {
  const a = "abcdefghijklmnopqrstuvwxyz234567";
  let bits = 0, value = 0, out = "";
  for (const byte of bytes) { value = (value << 8) | byte; bits += 8; while (bits >= 5) { out += a[(value >>> (bits - 5)) & 31]; bits -= 5; } }
  return bits > 0 ? out + a[(value << (5 - bits)) & 31] : out;
};
const hex = (buf: ArrayBuffer) => [...new Uint8Array(buf)].map((x) => x.toString(16).padStart(2, "0")).join("");
// Compares fixed-length digests so timing does not reveal how much of the token matched.
const safeEqual = async (a: string, b: string) => {
  const [x, y] = await Promise.all([a, b].map((v) => crypto.subtle.digest("SHA-256", new TextEncoder().encode(v))));
  const u = new Uint8Array(x), w = new Uint8Array(y);
  let diff = 0;
  for (let i = 0; i < u.length; i++) diff |= u[i] ^ w[i];
  return diff === 0;
};

// Builds the bundle once per kit and caches it in R2, so the checksum in the setup script always matches the bytes served.
async function bundle(env: Env, id: string): Promise<{ bytes: ArrayBuffer; sha: string; kit: KitRecord } | null> {
  if (!/^[a-z2-7]{20}$/.test(id)) return null;
  const kit = await env.REGISTRY.prepare("SELECT id, slug, name, published_at FROM kits WHERE id = ?").bind(id).first<KitRecord>();
  if (!kit) return null;
  const cached = await env.KITS.get(`kits/${id}/bundle.tar.gz`);
  if (cached) return { bytes: await cached.arrayBuffer(), sha: cached.customMetadata?.sha256 ?? "", kit };
  const source = await env.KITS.get(`kits/${id}/bitkit.kit.json`);
  if (!source) return null;
  const draft = bitkit.normalize(await source.json());
  const { files } = bitkit.generate(draft, new Date(kit.published_at));
  const tarBytes = bitkit.tar(files, kit.slug, kit.published_at);
  const bytes = await new Response(new Blob([tarBytes]).stream().pipeThrough(new CompressionStream("gzip"))).arrayBuffer();
  const sha = hex(await crypto.subtle.digest("SHA-256", bytes));
  await env.KITS.put(`kits/${id}/bundle.tar.gz`, bytes, { httpMetadata: { contentType: "application/gzip" }, customMetadata: { sha256: sha } });
  return { bytes, sha, kit };
}

async function apex(request: Request, env: Env, url: URL): Promise<Response> {
  if (url.pathname === "/api/kits" && request.method === "POST") {
    const auth = request.headers.get("authorization") ?? "";
    if (!(await safeEqual(auth, `Bearer ${env.PUBLISH_TOKEN}`))) return Response.json({ error: "unauthorized" }, { status: 401 });
    const draft = bitkit.normalize(await request.json());
    const problems = bitkit.problems(draft);
    if (problems.length) return Response.json({ error: "invalid kit", problems }, { status: 422 });
    const id = b32(crypto.getRandomValues(new Uint8Array(12))).slice(0, 20);
    const publishedAt = Date.now();
    await env.KITS.put(`kits/${id}/bitkit.kit.json`, JSON.stringify(draft), { httpMetadata: { contentType: "application/json" } });
    await env.REGISTRY.prepare("INSERT INTO kits (id, slug, name, published_at) VALUES (?, ?, ?, ?)").bind(id, draft.brand.slug, draft.brand.name, publishedAt).run();
    return Response.json({ id, setup: `curl -fsSL ${url.origin}/setup/${id} | sh`, tarball: `${url.origin}/kits/${id}.tar.gz`, publishedAt }, { status: 201 });
  }
  let m = url.pathname.match(/^\/kits\/([a-z2-7]+)\.tar\.gz$/);
  if (m && request.method === "GET") {
    const b = await bundle(env, m[1]);
    if (!b) return new Response("Unknown kit", { status: 404 });
    return new Response(b.bytes, { headers: { "content-type": "application/gzip", "x-bitkit-sha256": b.sha, "cache-control": "public, max-age=31536000, immutable" } });
  }
  m = url.pathname.match(/^\/setup\/([a-z2-7]+)$/);
  if (m && request.method === "GET") {
    const b = await bundle(env, m[1]);
    if (!b) return new Response("echo 'bitkit: unknown kit id' >&2; exit 1\n", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
    const script = bitkit.setupScript({ id: b.kit.id, slug: b.kit.slug, name: b.kit.name, sha: b.sha, origin: url.origin });
    return new Response(script, { headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } });
  }
  if (url.pathname === "/") return new Response(`bitkit: brand identity kits\n\nRun a kit's setup with:\n  curl -fsSL ${url.origin}/setup/<kit-id> | sh\n`, { headers: { "content-type": "text/plain; charset=utf-8" } });
  return new Response("Not found", { status: 404 });
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    // app.<zone>, the apex, and the workers.dev hostname serve the kit API; <slug>.<zone> is a tenant.
    if (url.hostname === APP || !url.hostname.endsWith(`.${APEX}`)) return apex(request, env, url);

    // Dynamic Workers: preview generated code in an isolate with no outbound network.
    if (url.pathname.startsWith("/_bitkit/sandbox/")) {
      const id = url.pathname.split("/")[3];
      const row = await env.REGISTRY.prepare("SELECT code FROM snippets WHERE id = ?").bind(id).first<{ code: string }>();
      if (!row) return new Response("Unknown snippet", { status: 404 });
      const worker = env.LOADER.get(`snippet:${id}`, async () => ({
        compatibilityDate: "2026-11-08",
        mainModule: "main.js",
        modules: { "main.js": row.code },
        globalOutbound: null,
      }));
      return worker.getEntrypoint().fetch(request);
    }

    // Tenant routing: <slug>.bitkit.sh or a custom hostname mapped in the registry.
    const tenant = await env.REGISTRY.prepare("SELECT * FROM tenants WHERE hostname = ? AND status = 'active'").bind(url.hostname).first<Tenant>();
    if (!tenant) return new Response("No site here yet", { status: 404 });
    try {
      return await env.TENANTS.get(tenant.script).fetch(request);
    } catch (e) {
      if (e instanceof Error && e.message.startsWith("Worker not found")) return new Response("Site is being set up", { status: 503 });
      throw e;
    }
  },
} satisfies ExportedHandler<Env>;

// Provisions one tenant from a bitkit.kit.json. Each step is retried on its own.
// Creates resources in the PLATFORM account, never in the owner's, and never
// creates social or registrar accounts.
type ProvisionParams = { kit: { brand: { slug: string; name: string }; services: string[] } };
export class ProvisionTenant extends WorkflowEntrypoint<Env, ProvisionParams> {
  async run(event: WorkflowEvent<ProvisionParams>, step: WorkflowStep) {
    const { kit } = event.payload;
    if (RESERVED_SLUGS.has(kit.brand.slug)) throw new Error(`slug ${kit.brand.slug} is reserved`);
    const slug = kit.brand.slug, script = `tenant-${slug}`, hostname = `${slug}.${this.env.PLATFORM_ZONE}`;
    const api = (path: string, init: RequestInit = {}) =>
      fetch(`https://api.cloudflare.com/client/v4/accounts/${this.env.CF_ACCOUNT_ID}${path}`, {
        ...init,
        headers: { authorization: `Bearer ${this.env.CF_PLATFORM_TOKEN}`, "content-type": "application/json" },
      }).then(async (r) => { const j = await r.json<{ success: boolean; errors: unknown; result: any }>(); if (!j.success) throw new Error(JSON.stringify(j.errors)); return j.result; });

    const resources = await step.do("create resources", async () => {
      const out: Record<string, string> = {};
      if (kit.services.includes("kv")) out.kv = (await api("/storage/kv/namespaces", { method: "POST", body: JSON.stringify({ title: `${slug}-cache` }) })).id;
      if (kit.services.includes("d1")) out.d1 = (await api("/d1/database", { method: "POST", body: JSON.stringify({ name: `${slug}-db` }) })).uuid;
      if (kit.services.includes("r2")) { await api("/r2/buckets", { method: "POST", body: JSON.stringify({ name: `${slug}-media` }) }); out.r2 = `${slug}-media`; }
      return out;
    });
    await step.do("register tenant", async () => {
      await this.env.REGISTRY.prepare("INSERT OR REPLACE INTO tenants (slug, script, hostname, owner, status, resources) VALUES (?, ?, ?, ?, 'pending', ?)")
        .bind(slug, script, hostname, "", JSON.stringify(resources)).run();
    });
    // The tenant's code is deployed with `npx cf@latest deploy --dispatch-namespace bitkit-tenants`, then activated here.
    await step.waitForEvent("tenant deployed", { type: "tenant-deployed", timeout: "7 days" });
    await step.do("activate", async () => {
      await this.env.REGISTRY.prepare("UPDATE tenants SET status = 'active' WHERE slug = ?").bind(slug).run();
    });
    return { slug, hostname, resources };
  }
}
